/* ---------------------------------------------------------------------------
 * The table of the routines
 *
 * The Scheme name, the number of arguments, and the shim, not the raw tmg_*
 * entry point.  The routines of an optional feature are in the table only
 * when it is built, so that (defined? 'name) tells whether the build has
 * them.
 * ------------------------------------------------------------------------- */

