static const int tmg_entry_count=
  (int) (sizeof (tmg_entries) / sizeof (tmg_entries[0]));

/* ---------------------------------------------------------------------------
 * Registration
 * ------------------------------------------------------------------------- */

/* The routines for boot-chez.scm, which defines them while it is loaded:
   a list of (name arity . address), the address of the shim, which
   foreign-procedure takes in place of the name of a foreign symbol. */
static tmscm
tm_glue_table () {
  tmscm l= Snil;
  for (int i= tmg_entry_count - 1; i >= 0; i--)
    l= Scons (Scons (Sstring_to_symbol (tmg_entries[i].name),
                     Scons (Sfixnum (tmg_entries[i].arity),
                            Sunsigned ((uptr) tmg_entries[i].fn))),
              l);
  return l;
}

static bool tmg_registered= false;

/* Called from custom_init(), i.e. inside Sbuild_heap() before the boot files
   are evaluated, so that boot-chez.scm -- and any secondary boot file loaded
   during heap construction -- has the glue. */
void
initialize_glue_chez () {
  if (tmg_registered) return;
  tmg_registered= true;
  Sforeign_symbol ("tm_glue_table", (void*) tm_glue_table);
}

int
chez_glue_procedure_count () {
  return tmg_entry_count;
}
